const config = $input.first().json;
const days = config.LOOKBACK_DAYS || 7;
const now = new Date();
const sinceDate = new Date(now.getTime() - days * 24 * 60 * 60 * 1000);

return {
  json: {
    ...config,
    since_iso: sinceDate.toISOString(),
    until_iso: now.toISOString(),
    since_formatted: sinceDate.toISOString().split('T')[0],
    until_formatted: now.toISOString().split('T')[0]
  }
};

const config = $('Compute Lookback Range').first().json;

// Safely collect commits
let commitsData = [];
try {
  const rawCommits = $('Fetch GitHub Commits').all();
  if (Array.isArray(rawCommits)) {
    commitsData = rawCommits.map(item => item.json).filter(c => c && c.commit);
  }
} catch (e) {
  commitsData = [];
}

// Safely collect issues & PRs
let issuesData = [];
try {
  const rawIssues = $('Fetch GitHub Closed Issues & PRs').all();
  if (Array.isArray(rawIssues)) {
    issuesData = rawIssues.map(item => item.json).filter(i => i && i.title);
  }
} catch (e) {
  issuesData = [];
}

// Distinguish merged PRs from regular closed issues
const closedPRs = issuesData.filter(item => item.pull_request !== undefined);
const closedIssues = issuesData.filter(item => item.pull_request === undefined);

// Prepare summary digest
const commitList = commitsData.slice(0, 30).map(c => `- ${c.commit.message.split('\n')[0]} (${c.commit.author ? c.commit.author.name : 'Unknown'})`).join('\n');
const prList = closedPRs.slice(0, 20).map(p => `- #${p.number}: ${p.title} (by @${p.user ? p.user.login : 'unknown'})`).join('\n');
const issueList = closedIssues.slice(0, 20).map(i => `- #${i.number}: ${i.title} (by @${i.user ? i.user.login : 'unknown'})`).join('\n');

const isFR = (config.LANGUAGE || 'EN').toUpperCase() === 'FR';

const systemPrompt = isFR
  ? `Tu es un Lead Tech et Developer Advocate expert. Tu rédiges un rapport hebdomadaire dynamique, motivant et structuré de l'activité du dépôt GitHub "${config.GITHUB_OWNER}/${config.GITHUB_REPO}" pour l'équipe d'ingénierie et les parties prenantes. Sois clair, concis et mets en valeur la valeur produit livrée.`
  : `You are an expert Lead Engineer and Developer Advocate. You write an engaging, high-impact, and structured weekly narrative summary of GitHub repository activity for "${config.GITHUB_OWNER}/${config.GITHUB_REPO}" for engineering teams and stakeholders. Focus on shipped value, reliability, and team velocity.`;

const userPrompt = isFR
  ? `Voici l'activité du dépôt ${config.GITHUB_OWNER}/${config.GITHUB_REPO} pour la semaine du ${config.since_formatted} au ${config.until_formatted}:

` +
    `STATISTIQUES:
- Commits: ${commitsData.length}
- Pull Requests mergées / traitées: ${closedPRs.length}
- Issues fermées / résolues: ${closedIssues.length}

` +
    `COMMITS RÉCENTS:
${commitList || 'Aucun commit cette semaine'}

` +
    `PULL REQUESTS:
${prList || 'Aucune PR cette semaine'}

` +
    `ISSUES FERMÉES:
${issueList || 'Aucune issue fermée cette semaine'}

` +
    `Consignes:
1. Rédige un résumé narratif captivant en français avec des emojis pertinents.
2. Inclus les sections suivantes: 🚀 Temps forts & Jalons majeurs, 🛠️ Fonctionnalités & PRs clés, 🐛 Corrections & Stabilité, 📊 Métriques de vélocité, 🎯 Prochains axes.
3. Formate en Markdown soigné adapté pour Discord/Slack.`
  : `Here is the repository activity for ${config.GITHUB_OWNER}/${config.GITHUB_REPO} for the week of ${config.since_formatted} to ${config.until_formatted}:

` +
    `METRICS:
- Total Commits: ${commitsData.length}
- Merged/Closed Pull Requests: ${closedPRs.length}
- Closed Issues: ${closedIssues.length}

` +
    `RECENT COMMITS:
${commitList || 'No commits recorded this week'}

` +
    `PULL REQUESTS:
${prList || 'No pull requests closed/merged this week'}

` +
    `CLOSED ISSUES:
${issueList || 'No issues closed this week'}

` +
    `Instructions:
1. Write an engaging, narrative engineering recap in English with appropriate emojis.
2. Include these sections: 🚀 Weekly Highlights & Milestones, 🛠️ Key Features & Merged PRs, 🐛 Bug Fixes & System Stability, 📊 Velocity Metrics, 🎯 Focus for Next Sprint.
3. Format in clean, punchy Markdown optimized for team Slack/Discord channels.`;

return {
  json: {
    ...config,
    metrics: {
      totalCommits: commitsData.length,
      totalPRs: closedPRs.length,
      totalIssues: closedIssues.length
    },
    anthropicPayload: {
      model: config.CLAUDE_MODEL || "claude-sonnet-4-20250514",
      max_tokens: 1500,
      system: systemPrompt,
      messages: [
        {
          role: "user",
          content: userPrompt
        }
      ]
    }
  }
};

const claudeResponse = $input.first().json;
const prevContext = $('Aggregate Activity & Build Prompt').first().json;

let narrativeText = "No content generated";
if (claudeResponse && claudeResponse.content && claudeResponse.content[0] && claudeResponse.content[0].text) {
  narrativeText = claudeResponse.content[0].text;
} else if (typeof claudeResponse === 'string') {
  narrativeText = claudeResponse;
}

const channel = (prevContext.DELIVERY_CHANNEL || 'discord').toLowerCase();
const title = `Weekly Engineering Summary: ${prevContext.GITHUB_OWNER}/${prevContext.GITHUB_REPO}`;

let payload = {};
if (channel === 'slack') {
  payload = {
    text: `*${title}*\n\n${narrativeText}`,
    blocks: [
      {
        type: "header",
        text: {
          type: "plain_text",
          text: title,
          emoji: true
        }
      },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: narrativeText
        }
      }
    ]
  };
} else {
  // Discord default (supports embeds and markdown)
  payload = {
    username: "Claude Dev Bot",
    content: `**${title}**\n\n${narrativeText.length > 1900 ? narrativeText.substring(0, 1900) + '...' : narrativeText}`
  };
}

return {
  json: {
    ...prevContext,
    rawSummary: narrativeText,
    webhookPayload: payload
  }
};
